'use client';

import React, { useState } from 'react';
import Modal from '../ui/Modal';
import { useModal } from '../../context/ModalContext';
import styles from './ContactModal.module.css';

const ContactModal = () => {
    const { isOpen, closeModal } = useModal();
    const [formData, setFormData] = useState({
        name: '',
        phone: '',
        description: ''
    });

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            const response = await fetch('/api/contact', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(formData)
            });

            if (response.ok) {
                alert('Заявка отправлена! Мы свяжемся с вами в ближайшее время.');
                setFormData({ name: '', phone: '', description: '' });
                closeModal();
            } else {
                alert('Ошибка при отправке. Пожалуйста, попробуйте позже.');
            }
        } catch (error) {
            alert('Произошла ошибка связи с сервером.');
        }
    };

    return (
        <Modal isOpen={isOpen} onClose={closeModal}>
            <div className={styles.container}>
                <h2 className={styles.title}>Оставить заявку на расчет</h2>
                <p className={styles.subtitle}>Заполните форму, и мы рассчитаем стоимость вашего проекта в течение часа.</p>

                <form className={styles.form} onSubmit={handleSubmit}>
                    <div className={styles.inputGroup}>
                        <label>Ваше имя</label>
                        <input
                            type="text"
                            placeholder="Введите имя"
                            required
                            value={formData.name}
                            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                        />
                    </div>

                    <div className={styles.inputGroup}>
                        <label>Телефон / Telegram</label>
                        <input
                            type="text"
                            placeholder="+7 (___) ___-__-__"
                            required
                            value={formData.phone}
                            onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                        />
                    </div>

                    <div className={styles.inputGroup}>
                        <label>Описание задачи</label>
                        <textarea
                            rows={4}
                            placeholder="Опишите вашу деталь, материал или прикрепите ссылку на файлы..."
                            value={formData.description}
                            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                        ></textarea>
                    </div>

                    <div className={styles.actions}>
                        <div className={styles.fileHint}>Файлы можно отправить после созвона или в Telegram</div>
                        <button type="submit" className="primary-button primary-button--filled">
                            Отправить заявку
                        </button>
                    </div>
                </form>
            </div>
        </Modal>
    );
};

export default ContactModal;
